import{_ as o,l as i,o as e,c as l,v as r,p as s,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"央行资产负债表","description":"","frontmatter":{"title":"央行资产负债表","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/central-bank-balance-sheet.md","filePath":"econ/central-bank-balance-sheet.md","lastUpdated":1789023840000}'),E={name:"econ/central-bank-balance-sheet.md"};function p(B,a,_,m,u,A){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="央行资产负债表" tabindex="-1">央行资产负债表 <a class="header-anchor" href="#央行资产负债表" aria-label="Permalink to &quot;央行资产负债表&quot;">​</a></h1><div class="epigraph"><p>政策利率撞上零之后，工具变成规模、久期与对手方。资产负债表是非常规货币的会计，不是装饰。</p><footer>—— Bernanke, The Federal Reserve and the Financial Crisis；对照 Curdia and Woodford 对 QE 的理论讨论</footer></div><p><a href="/econ/shadow-run">上一课</a>把停滚写进回购与 ABCP。缺口是谁在停滚之后持有那些资产：央行扩表。本课钉资产负债表；回购与 MMF 的制度下一课再拆。不重写 Leeper 的主动被动，只补工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统工具是短期政策利率。ZLB 或储备充裕之后，利率走廊要靠 IOER/ON RRP 一类地板，数量与久期变成独立维度。QE：买长债压期限溢价；信贷宽松：买或担保私人资产。若只把扩表写成「印钱」，会把储备、财政债和信用风险混成一个 \\(M\\)。缺口是分清资产侧（谁的债）和负债侧（储备 vs 现金 vs 逆回购）。</p><p><span class="marginnote">Gertler and Karadi 把央行信贷政策放进中介模型。Krishnamurthy and Vissing-Jorgensen 的 QE 事件研究。Reis 对央行资本与再分配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一张表：资产（国债、MBS、贷款）、负债（现金、储备、政府存款、ON RRP）、资本。政策实验：扭转操作改久期、QE 改规模、对手方资格改谁能借。退出：缩表与付息储备是同一套走廊的另一侧。与财政主导：付息储备把货币负债变成类国债，主导问题更贴预算。</p>',8)),(e(),s(h,null,{default:t(()=>[c(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASSET%5B%22%E5%9B%BD%E5%80%BA%20%2F%20MBS%20%2F%20%E4%BF%A1%E8%B4%B7%22%5D%20--%3E%20SIZE%5B%22%E8%A7%84%E6%A8%A1%E4%B8%8E%E4%B9%85%E6%9C%9F%22%5D%0A%20%20LIAB%5B%22%E5%82%A8%E5%A4%87%20%2F%20RRP%22%5D%20--%3E%20FLOOR%5B%22%E5%88%A9%E7%8E%87%E5%9C%B0%E6%9D%BF%22%5D%0A%20%20SIZE%20--%3E%20TP%5B%22%E6%9C%9F%E9%99%90%E6%BA%A2%E4%BB%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>QE 的组合平衡：长期安全资产被抽走，私人要再平衡到其他久期，压 \\(r^L\\)（Vayanos–Vila 的首选生境）。信贷政策直接替换中介的 \\(\\phi\\)。负债侧付息使「数量」不再一对一决定隔夜利率。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估某一次 QE 的乘数点估计。下一课把负债侧的 ON RRP 与 MMF、回购连成同一套短债生态。不把 CBDC 当已落地的负债科目。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扩表要分资产侧信用/久期与负债侧地板工具。</li><li>QE 走组合平衡与中介约束，不是单纯 \\(M\\)。</li><li>出处：Bernanke 危机讲义；KVJ 事件研究；Gertler–Karadi。</li></ul>',6))])}const P=o(E,[["render",p]]);export{b as __pageData,P as default};
